// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: any address is admissible, including the zero address.
        address caller = c.owner();
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // Rule: after any successful transferOwnership, the owner is never the zero address.
            assertTrue(c.owner() != address(0));
        } catch {
            // The reference reverts exactly when newOwner is the zero address; owner unchanged and nonzero.
            assertTrue(newOwner == address(0) && c.owner() == caller);
        }
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
